struct Tracer {
    static inline int copies{ 0 };
    static inline int moves{ 0 };
    Tracer() = default;
    Tracer(const Tracer&) { ++copies; }
    Tracer(Tracer&&) noexcept { ++moves; }
};
struct Holder { Tracer t; int n; Holder(Tracer tracer, int number) : t{ std::move(tracer) }, n{ number } {} };
struct Pair { std::string a; int b; Pair(std::string first, int second) : a{ std::move(first) }, b{ second } {} };

TEST("make builds from its arguments") { const auto p{ make<Pair>("hello", 5) }; CHECK(p != nullptr); if (p) { CHECK_EQ(p->a, "hello"); CHECK_EQ(p->b, 5); } }
TEST("make copies nothing when given a temporary") { Tracer::copies = 0; const auto h{ make<Holder>(Tracer{}, 7) }; CHECK_EQ(Tracer::copies, 0); CHECK_EQ(h->n, 7); }
TEST("make copies exactly once when given an lvalue") { Tracer::copies = 0; Tracer keep{}; const auto h{ make<Holder>(keep, 1) }; CHECK_EQ(Tracer::copies, 1); }
TEST("emplaceBack") { std::vector<Pair> v; v.reserve(4); Pair& first{ emplaceBack(v, "a", 1) }; emplaceBack(v, std::string{ "b" }, 2); CHECK_EQ(v.size(), 2u); CHECK_EQ(first.a, "a"); CHECK_EQ(v[1].b, 2); CHECK(&first == &v[0]); }
TEST("emplaceBack copies nothing when given a temporary") { std::vector<Holder> v; v.reserve(2); Tracer::copies = 0; emplaceBack(v, Tracer{}, 3); CHECK_EQ(Tracer::copies, 0); }

